#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/python/tasks/setup-deps-python.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Install the Python dependencies; --upgrade also upgrades them"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--upgrade" help="also upgrade the dependencies to their latest versions"

import os
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

root = os.environ["MISE_PROJECT_ROOT"]

# Shipped with the python tool. Without a pyproject.toml, this is not a Python
# project, so the task does not apply and prints nothing.
if not os.path.isfile(f"{root}/pyproject.toml"):
  sys.exit(0)

if os.environ.get("usage_upgrade") == "true":
  helpers.print_header("Upgrading Python dependencies ...")
  result = helpers.tool("uv", "sync", "--directory", root, "--upgrade")
else:
  helpers.print_header("Installing Python dependencies ...")
  # `--locked` installs from uv.lock and fails, rather than rewriting it, when
  # the lockfile no longer matches pyproject.toml.
  result = helpers.tool("uv", "sync", "--directory", root, "--locked")
sys.exit(result.returncode)
